use vstd::prelude::*;

verus! {
    /// Determines whether a food is "delicious", "safe", or "dangerous"
    /// based on how many days have passed since a reference day.
    ///
    /// days_past = b − a
    /// - if days_past ≤ 0           ⇒ "delicious"
    /// - else if days_past ≤ x      ⇒ "safe"
    /// - else                       ⇒ "dangerous"
    fn determine_food_safety(x: i8, a: i8, b: i8) -> (&'static str)
        requires
            // threshold must be non‐negative
            x >= 0,
        ensures
            // result is exactly the string given by the logical classification:
            result ==
              if (b as i32) - (a as i32) <= 0 {
                  "delicious"
              } else if (b as i32) - (a as i32) <= (x as i32) {
                  "safe"
              } else {
                  "dangerous"
              }
    {
        // do the subtraction in i32 so we never overflow
        let days: i32 = (b as i32) - (a as i32);
        if days <= 0 {
            "delicious"
        } else if days <= (x as i32) {
            "safe"
        } else {
            "dangerous"
        }
    }
}

